def compute_dynamic_programming(str1: Union[str, List[str]], str2: Union[str, List[str]]) -> float:
    n = len(str1)
    m = len(str2)

    # Initialize the distance matrix.
    dist = {}
    for i in range(n+1):
        for j in range(m+1):
            dist[(i, j)] = 0

