    # d[i, j] := min(d[i-1, j-1] + mismatch(i, j), d[i-1, j] + 1, d[i, j-1] + 1),
    # where mismatch(i, j) is 1 if str1[i] != str2[j] and 0 otherwise.
    for i in range(1, n+1):
        for j in range(1, m+1):
