            dist[(i, j)] = min(
                dist[(i-1, j-1)] + (self.substitute_weight if str1[i-1] != str2[j-1] else self.match_weight),
                self.delete_weight + dist[(i-1, j)], 
                dist[(i, j-1)] + self.insert_weight,
            )

    return dist[(n, m)]
