        while (c1 < l1) and (c2 < l2):
            if options.tokenmatcher(t1[c1], t2[c2]):
                local_cs += options.matchingevaluator(t1[c1], t2[c2])
                is_trans = False
                offset_arr = [ {'c1': c1, 'c2': c2} ]
            else:
                lcss += options.locallengthevaluator(local_cs)
                local_cs = 0
                if c1 != c2:
                    c1 = c2 = min(c1, c2)
                for i in range(maxoffset):
                    if (c1 + i < l1) or (c2 + i < l2):
                        if (c1 + i < l1) and options.tokenmatcher(t1[c1 + i], t2[c2]):
                            c1 += i - 1
                            c2 -= 1
                            break
                        if (c2 + i < l2) and options.tokenmatcher(t1[c1], t2[c2 + i]):
                            c1 -= 1
                            c2 += i - 1
                            break
                    elif (c1 + i == l1) and options.tokenmatcher(t1[-1], t2[c2]):  # Handle single character transpositions at the end
                        c1 += i - 1
                        local_cs += options.locallengthevaluator(0)
                        break
                    elif (c2 + i == l2) and options.tokenmatcher(t1[c1], t2[-1]):  # Handle single character transpositions at the end
                        c2 += i - 1
                        local_cs += options.locallengthevaluator(0)
                        break
