                            break
                    elif (c1 - i >= 0) or (c2 - i >= 0):
                        if (c1 - i >= 0) and options.tokenmatcher(t1[c1 - i], t2[c2]):
                            c1 -= i
                            c2 += 1
                            break
                            offset_arr.append({'c1': c1, 'c2': c2, 'trans': True})
