        return ''.join(mapping[char] for char in string)

    while pos < size:
        result, current = in_trie(current, string[pos])

        if result == TrieResult.FAILED:
            if sym:
                last_match_length = pos - 1 - (len(sym) - 1) // 2
                chunks.append(sym)
                sym = None
            else:
                chunks.append(string[pos])
                pos += 1

        end = pos + 1
        end_match_length = start
        if current.get(pos):
            while end <= size and current.get(end) is not None:
                end += 1
                end_match_length = end - 1

            if end_match_length - last_match_length > 1:
                prefix = string[last_match_length:end_match_length]
                if all(prefix[i] in mapping for i in range(len(prefix))):
                    chunks.extend(string[last_match_length:end_match_length])
