from typing import Union, Tuple, List

def compute(str1: Union[str, List[str]], str2: Union[str, List[str]], returnCandidates: bool = False) -> Tuple[float, Union[List[str], List[List[str]]]]:
    n, m = len(str1), len(str2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    distance = dp[n][m]

    if returnCandidates:
        candidates = []
        i, j = n, m
        while i > 0 and j > 0:
            if str1[i - 1] == str2[j - 1]:
                candidates.append(str1[i - 1])
                i, j = i - 1, j - 1
            elif dp[i - 1][j] > dp[i][j - 1]:
                i -= 1
            else:
                j -= 1

        return distance, list(reversed(candidates))[::-1]
    else:
        return distance

